import paymentCoreService from '../services/paymentCore.js';
import paymentRailsService from '../services/paymentRails.js';
import auditEmitter from '../utils/auditEmitter.js';

export const searchMerchants = async (req, res) => {
  try {
    const { merchantId, startDate, endDate, status } = req.query;
    const coreResults = await paymentCoreService.searchMerchants({ merchantId, startDate, endDate, status });
    const railResults = await paymentRailsService.getBatchStatuses(coreResults.map(r => r.batchId));
    const merged = coreResults.map(r => ({ ...r, railStatus: railResults[r.batchId] || 'unknown' }));
    await auditEmitter.emit({ action: 'search', user: req.user.id, role: req.user.role, payload: { merchantId, status } });
    return res.json({ results: merged, count: merged.length });
  } catch (err) {
    console.error('Search failed', err);
    return res.status(500).json({ error: 'Search failed' });
  }
};

import paymentRailsService from '../services/paymentRails.js';
import auditEmitter from '../utils/auditEmitter.js';

export const getSettlementTimeline = async (req, res) => {
  try {
    const { batchId } = req.params;
    const events = await paymentRailsService.getSettlementTimeline(batchId);
