import paymentActionsService from '../services/paymentActions.js';
import paymentRailsService from '../services/paymentRails.js';
import auditEmitter from '../utils/auditEmitter.js';

export const triggerRefund = async (req, res) => {
  try {
    const { paymentId, reason, amount } = req.body;
    const response = await paymentActionsService.triggerRefund({ paymentId, reason, amount });
    await auditEmitter.emit({ action: 'refund', user: req.user.id, role: req.user.role, payload: { paymentId, amount } });
    return res.json({ status: 'initiated', actionId: response.id });
  } catch (err) {
    console.error('Refund error', err);
    res.status(500).json({ error: 'Refund initiation failed' });
  }
};

export const approvePayout = async (req, res) => {
  try {
    if (req.user.role !== 'Manager')
      return res.status(403).json({ error: 'Not authorized' });
    const { payoutId } = req.body;
    const approval = await paymentRailsService.approvePayout(payoutId);
    const auditId = await auditEmitter.emit({ action: 'approve_payout', user: req.user.id, role: req.user.role, payload: { payoutId } });
    return res.json({ payoutId, status: 'approved', auditLogId: auditId });
  } catch (err) {
    console.error('Approval error', err);
    res.status(500).json({ error: 'Approval failed' });
  }
};

export const requireRole = (roles) => {
  return (req, res, next) => {
    const { role } = req.user || {};
    if (!role || !roles.includes(role)) {
      return res.status(403).json({ error: 'Access denied' });
    }
    next();
  };
};

import { Kafka } from 'kafkajs';
import AWS from 'aws-sdk';
const s3 = new AWS.S3({ region: 'us-east-1' });
const kafka = new Kafka({ brokers: [process.env.KAFKA_BROKER], clientId: 'payment-admin' });
const producer = kafka.producer();

await producer.connect();

const emit = async (log) => {
  const msg = { ...log, timestamp: new Date().toISOString() };
  try {
    await producer.send({ topic: 'audit.payments', messages: [{ value: JSON.stringify(msg) }] });
    const key = `audit/${Date.now()}-${log.action}.json`;
    await s3.putObject({ Bucket: process.env.AUDIT_S3_BUCKET, Key: key, Body: JSON.stringify(msg) }).promise();
    return key;
  } catch (err) {
    console.error('Audit emission error', err);
    // Retry logic could be added here
    throw err;
  }
};

export default { emit };
